import org.eclipse.jface.text.rules.ICharacterScanner;

class PatternRule {
    protected boolean fBreaksOnEOF = true;
    protected char[] fStartSequence = new char[] {'a'};

    protected boolean sequenceDetected(ICharacterScanner scanner, char[] sequence, boolean eofAllowed) {
        return true;
    }

    public void applyRule(ICharacterScanner scanner) {
        int c = scanner.read();
        if (c == fStartSequence[0]) {
            if (sequenceDetected(scanner, fStartSequence, fBreaksOnEOF)) { // Changed line
                System.out.println("Matched");
            }
        }
    }
}

interface ICharacterScanner {
    int read();
}

